  pose proof HALGS as SPA.
  try (unfold asn1_get_alg_stmt, U_ASN1_GET_ALG in SPA).
  unfold x509_get_alg_stmt, U_X509_GET_ALG.
  intros until ppw.
  intros HPP HALG HPAR HBUF B1 B2 B3 B4 D1 D1b D1c D2 D3 D3b AL1 AL2 AL3 NZ1 NZ2 NZ4 NZ3 ST SLO ACL SPA16
