  pose proof alloc_ceiling_pos as ACP.
  pose proof (bv_unsigned_in_range 64 sp) as SPR.
  try (unfold bv_modulus in SPR).
  try (cbn in SPR).
  pose proof (munch_refl [(PP, PP + 8); (ALG, ALG + 24); (PAR, PAR + 24); (bv_unsigned sp - 80, bv_unsigned sp)] m) as MU.
  pose proof (wmono_refl usegs m) as WM.
  carve_frame 16%nat ST.
  lxp_split_frame [8;8]%nat.
  (* [comment removed for export] *)
  pose proof (@sums4_ok _ _ ltac:(eassumption) ltac:(eassumption) ltac:(eassumption)) as LXSUMS.
  lxp_run (PLANS [] [(0x25e00, DSplit)] 32%N SUMS4).
  (* [comment removed for export] *)
  all: first [ lxp_ret ].
Qed.
